import type { PropsLocale } from '@deepseek-ai/dsh-client-ui-slots'
import type {
  SidebarBrandMarkOwnerProps, SidebarBrandNameOwnerProps,
} from '@deepseek-ai/dsh-client-ui-sidebar/client'
import { NS } from './locales.ts'
import css from './Brand.module.css'

const SUIXING_LOGO = 'data:image/png;base64,'

/**
 * Render the SuiXing mark from the product-supplied raster artwork.
 * @param props - Host-supplied mark presentation.
 * @returns the SuiXing mark at the requested square size.
 */
export function SuiXingBrandMark({ size }: SidebarBrandMarkOwnerProps) {
  return <img className={css.mark} src={SUIXING_LOGO} width={size} height={size} alt="" />
}

/** Owner share plus this plugin's own namespace-bound translate seat. */
export type SuiXingBrandNameProps = SidebarBrandNameOwnerProps & PropsLocale<typeof NS>

/**
 * Render the SuiXing product name without duplicating the adjacent mark.
 * @param props - owner share plus the namespace-bound translate seat.
 * @returns the product name for the active locale.
 */
export function SuiXingBrandName({ t }: SuiXingBrandNameProps) {
  return <span className={css.name}>{t('brand.name')}</span>
}
